// The park (M4 W12, AB-T-0584): the sample's second set, made with Gaea. A small paved square beside the cafe, with
// hedges on three sides, a lawn and four props generated by the local Gaea (tools/generate-park.mjs: a bench, a street
// lamp, a tree in a planter and a drinks vending machine). This tool writes what isn't generated:
// - sets/park.glb: the paving, kerbs, lawns and hedges as boxes with flat colours, and KHR_physics colliders for the
//   ground, the hedges and each prop (invisible boxes, so the props' 40,000-face meshes need no colliders of their own);
// - park.vrmxs: the set scene (sky, sun, the props, Mira and Hana standing for the camera, a camera), validated;
// - scripts/park-marks.json: marks for scripts filmed here (the creator finds them for a script whose `Set:` is park.vrmxs).
//   node content/sample/tools/make-park.mjs
import fs from 'node:fs';
import path from 'node:path';
import { writeGLB } from '@vrmxg/model';
import { serialize, createValidator } from '@vrmxg/scene';
import { m0Registry } from '@vrmxg/registry/m0';

const root = path.resolve(import.meta.dirname, '..');
const GEN = 'VRMXG sample content (content/sample/tools/make-park.mjs)';
const C = { grass: '#7da35a', paving: '#c9c3b8', kerb: '#9d978c', lawn: '#6f9a4e', hedge: '#3f6b35', soil: '#6b5440' };
const W = 10, D = 10, HEDGE = { h: 0.9, t: 0.6 };
const yaw = (deg) => { const a = (deg * Math.PI) / 180; return [0, +Math.sin(a / 2).toFixed(7), 0, +Math.cos(a / 2).toFixed(7)]; };

/**
 * The props: where each stands on the ground, its turn (Gaea's TRELLIS.2 meshes face +x: the bench's back is at −x), and
 * the box it collides as, in the mesh's own frame (turned with it). Gaea centres each mesh on its origin, so the Model node is lifted by the mesh's own lowest point
 * (read from the GLB: groundLift).
 */
export const PROPS = [
  { id: 'bench', name: 'Bench', p: [0, 0, -3.3], yaw: -90, collider: { size: [0.7, 0.85, 1.7], y: 0.425 } },
  { id: 'street-lamp', name: 'Street lamp', p: [-2.4, 0, -3.6], yaw: 0, collider: { size: [0.3, 3.4, 0.3], y: 1.7 } },
  { id: 'planter-tree', name: 'Tree in a planter', p: [2.9, 0, -3.3], yaw: 20, collider: { size: [0.6, 0.5, 0.6], y: 0.25 } },
  { id: 'vending-machine', name: 'Vending machine', p: [-4.2, 0, -0.4], yaw: 0, collider: { size: [1.0, 1.85, 0.85], y: 0.925 } },
];

export const MARKS = {
  'by-the-bench': { p: [0.5, 0, -2.4] },
  'bench-side': { p: [-1.1, 0, -2.2], q: yaw(60) },
  'by-the-machine': { p: [-3.1, 0, -0.4], q: yaw(-90) },
  'on-the-path': { p: [1.4, 0, 1.2], q: yaw(200) },
};

/** How far a Gaea GLB's mesh reaches below its origin (metres, after Gaea's mes_placement scale and offset). */
export function groundLift(bytes) {
  const b = Buffer.from(bytes), len = b.readUInt32LE(12), j = JSON.parse(b.subarray(20, 20 + len).toString());
  const place = j.nodes.find((n) => n.name === 'mes_placement') ?? { scale: [1, 1, 1], translation: [0, 0, 0] };
  let low = Infinity;
  for (const m of j.meshes) for (const pr of m.primitives) low = Math.min(low, j.accessors[pr.attributes.POSITION].min[1]);
  return +(-(low * (place.scale?.[1] ?? 1) + (place.translation?.[1] ?? 0))).toFixed(4);
}

function parts() {
  const out = [
    // the ground: grass all round (wide enough that no shot sees its edge), the square paved within the hedges and out
    // to the front, where the path leads to the cafe
    { name: 'ground', size: [40, 0.2, 40], p: [0, -0.1, 0], color: C.grass, collider: true },
    { name: 'paving', size: [W, 0.004, D + 2], p: [0, 0.002, 1], color: C.paving },
    // lawns either side of the bench, edged with kerbs
    { name: 'lawn-left', size: [3.2, 0.06, 2.4], p: [-2.6, 0.03, -3.4], color: C.lawn },
    { name: 'lawn-right', size: [3.2, 0.06, 2.4], p: [2.6, 0.03, -3.4], color: C.lawn },
    { name: 'kerb-back', size: [W - 1.2, 0.08, 0.12], p: [0, 0.04, -2.14], color: C.kerb },
    // the square's paving pattern: a darker band across it
    { name: 'band', size: [W - 1.2, 0.006, 0.5], p: [0, 0.006, 0.6], color: C.kerb },
  ];
  // hedges on three sides (the front, +z, is open: the camera's side and the way to the cafe)
  out.push({ name: 'hedge-back', size: [W, HEDGE.h, HEDGE.t], p: [0, HEDGE.h / 2, -D / 2 + HEDGE.t / 2], color: C.hedge, collider: true });
  for (const s of [-1, 1]) out.push({ name: `hedge-${s < 0 ? 'left' : 'right'}`, size: [HEDGE.t, HEDGE.h, D - HEDGE.t], p: [s * (W / 2 - HEDGE.t / 2), HEDGE.h / 2, HEDGE.t / 2], color: C.hedge, collider: true });
  // each prop's collider, an invisible box where it stands
  for (const pr of PROPS) out.push({ name: `${pr.id}-collider`, size: pr.collider.size, p: [pr.p[0], pr.collider.y, pr.p[2]], q: yaw(pr.yaw), visible: false, collider: true });
  return out;
}

export function parkScene(lift = {}) {
  return {
    format: 'vrmxs', version: 1, id: 'park',
    assets: [
      { id: 'park', type: 'glb', ref: 'sets/park.glb' },
      ...PROPS.map((pr) => ({ id: pr.id, type: 'glb', ref: `props/${pr.id}.glb` })),
      { id: 'mira', type: 'vrmxa', ref: 'characters/mira.vrmxa' },
      { id: 'hana', type: 'vrmxa', ref: 'characters/hana.vrmxa' },
    ],
    nodes: [
      { id: 'root', type: 'Node3D', name: 'Park' },
      { id: 'env', type: 'Environment', parent: 'root', props: { ambientIntensity: 0.6, background: 'gradient', environmentIntensity: 0.45, skyHorizonColor: '#eef1f4', skyTopColor: '#8fb3d9' } },
      { id: 'set', type: 'Model', parent: 'root', asset: 'park' },
      ...PROPS.map((pr) => ({ id: pr.id, type: 'Model', parent: 'root', name: pr.name, asset: pr.id, transform: { p: [pr.p[0], pr.p[1] + (lift[pr.id] ?? 0), pr.p[2]], ...(pr.yaw ? { q: yaw(pr.yaw) } : {}) }, props: { colliders: 'none' } })),
      { id: 'sun', type: 'DirectionalLight', parent: 'root', transform: { q: [-0.38, 0.28, 0.12, 0.873] }, props: { intensity: 2.6, shadowExtent: 9, shadowPreset: 'high' } },
      { id: 'mira', type: 'Character', parent: 'root', name: 'Mira', asset: 'mira', transform: { p: [1.4, 0, 1.2], q: yaw(200) } },
      { id: 'hana-1', type: 'Character', parent: 'root', name: 'Hana', asset: 'hana', transform: { p: [0.5, 0, -2.4] } },
      { id: 'cam', type: 'Camera', parent: 'root', transform: { p: [0, 1.6, 6.5] }, props: { focalLength: 30 } },
    ],
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)) {
  for (const pr of PROPS) if (!fs.existsSync(path.join(root, `props/${pr.id}.glb`))) { console.error(`props/${pr.id}.glb is missing: run tools/generate-park.mjs (needs Gaea)`); process.exit(1); }
  fs.writeFileSync(path.join(root, 'sets/park.glb'), writeGLB({ name: 'park', generator: GEN, parts: parts() }));
  const lift = Object.fromEntries(PROPS.map((pr) => [pr.id, groundLift(fs.readFileSync(path.join(root, `props/${pr.id}.glb`)))]));
  const doc = parkScene(lift);
  const v = createValidator(m0Registry()).check(doc, { prefabs: new Map() });
  if (v.errors.length) { console.error(v.errors); process.exit(1); }
  for (const w of v.warnings ?? []) console.warn(`warning: ${JSON.stringify(w)}`);
  fs.writeFileSync(path.join(root, 'park.vrmxs'), serialize(doc));
  const marks = { note: 'Marks for scripts filmed in the park (M4 W12): where the cast stands. The build places each as a Marker node in the sequence.', marks: MARKS };
  fs.writeFileSync(path.join(root, 'scripts/park-marks.json'), JSON.stringify(marks, null, 1) + '\n');
  console.log(`wrote sets/park.glb (${fs.statSync(path.join(root, 'sets/park.glb')).size} bytes), park.vrmxs (${doc.nodes.length} nodes), scripts/park-marks.json (${Object.keys(MARKS).length} marks)`);
}
